    14	/**
    15	 * Check to see if user has either a debit card or personal bank account added that can be used with a wallet.
    16	 */
    17	function hasExpensifyPaymentMethod(fundList: Record<string, Fund>, bankAccountList: Record<string, BankAccount>, shouldIncludeDebitCard = true): boolean {
    18	    const validBankAccount = Object.values(bankAccountList).some((bankAccountJSON) => {
    19	        const bankAccount = new BankAccountModel(bankAccountJSON);
    20	
    21	        return bankAccount.getPendingAction() !== CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE && bankAccount.isOpen() && bankAccount.getType() === CONST.BANK_ACCOUNT.TYPE.PERSONAL;
    22	    });
    23	
    24	    // Hide any billing cards that are not P2P debit cards for now because you cannot make them your default method, or delete them
    25	    const validDebitCard = Object.values(fundList).some((card) => card?.accountData?.additionalData?.isP2PDebitCard ?? false);
    26	
    27	    return validBankAccount || (shouldIncludeDebitCard && validDebitCard);
    28	}
    29	
    30	function getPaymentMethodDescription(accountType: AccountType, account: BankAccount['accountData'] | Fund['accountData'] | ACHAccount): string {
    31	    if (account) {
    32	        if (accountType === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT && 'accountNumber' in account) {
    33	            return `${Localize.translateLocal('paymentMethodList.accountLastFour')} ${account.accountNumber?.slice(-4)}`;
    34	        }
    35	        if (accountType === CONST.PAYMENT_METHODS.BUSINESS_BANK_ACCOUNT && 'accountNumber' in account) {
    36	            return `${Localize.translateLocal('paymentMethodList.accountLastFour')} ${account.accountNumber?.slice(-4)}`;
    37	        }
    38	        if (accountType === CONST.PAYMENT_METHODS.DEBIT_CARD && 'cardNumber' in account) {
    39	            return `${Localize.translateLocal('paymentMethodList.cardLastFour')} ${account.cardNumber?.slice(-4)}`;
    40	        }
    41	    }
    42	    return '';
    43	}
    44	
    45	/**
    46	 * Get the PaymentMethods list
    47	 */
    48	function formatPaymentMethods(bankAccountList: Record<string, BankAccount>, fundList: Record<string, Fund> | Fund[], styles: ThemeStyles): PaymentMethod[] {
    49	    const combinedPaymentMethods: PaymentMethod[] = [];
    50	
    51	    Object.values(bankAccountList).forEach((bankAccount) => {
    52	        // Add all bank accounts besides the wallet
    53	        if (bankAccount?.accountData?.type === CONST.BANK_ACCOUNT_TYPES.WALLET) {
    54	            return;
    55	        }
    56	
    57	        const {icon, iconSize, iconHeight, iconWidth, iconStyles} = getBankIcon({
    58	            bankName: bankAccount?.accountData?.additionalData?.bankName,
    59	            isCard: false,
    60	            styles,
    61	        });
    62	        combinedPaymentMethods.push({
    63	            ...bankAccount,
    64	            description: getPaymentMethodDescription(bankAccount?.accountType, bankAccount.accountData),
    65	            icon,
    66	            iconSize,
    67	            iconHeight,
    68	            iconWidth,
    69	            iconStyles,
    70	        });
    71	    });
    72	
    73	    Object.values(fundList).forEach((card) => {
    74	        const {icon, iconSize, iconHeight, iconWidth, iconStyles} = getBankIcon({bankName: card?.accountData?.bank, isCard: true, styles});
    75	        combinedPaymentMethods.push({
    76	            ...card,
    77	            description: getPaymentMethodDescription(card?.accountType, card.accountData),
    78	            icon,
    79	            iconSize,
    80	            iconHeight,
    81	            iconWidth,
    82	            iconStyles,
    83	        });
    84	    });
    85	
    86	    return combinedPaymentMethods;
    87	}
    88	
    89	function calculateWalletTransferBalanceFee(currentBalance: number, methodType: string): number {
    90	    const transferMethodTypeFeeStructure =
    91	        methodType === CONST.WALLET.TRANSFER_METHOD_TYPE.INSTANT ? CONST.WALLET.TRANSFER_METHOD_TYPE_FEE.INSTANT : CONST.WALLET.TRANSFER_METHOD_TYPE_FEE.ACH;
    92	    const calculateFee = Math.ceil(currentBalance * (transferMethodTypeFeeStructure.RATE / 100));
    93	    return Math.max(calculateFee, transferMethodTypeFeeStructure.MINIMUM_FEE);
    94	}
    95	
    96	export {hasExpensifyPaymentMethod, getPaymentMethodDescription, formatPaymentMethods, calculateWalletTransferBalanceFee};
